import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract Auction is ERC721, Ownable {
    using SafeMath for uint256;

    struct Bid {
        address bidder;
        uint256 value;
        uint256 timestamp;
    }

    Bid[] public bids;
    uint256 public currentHighestBid;
    Bid public highestBidder;
    uint256 public auctionEnd;

    constructor(uint256 _initialAuctionEnd) ERC721("Auction", "Auc") {
        auctionEnd = _initialAuctionEnd;
    }

    function placeBid(uint256 _bid) public payable {
        require(msg.value == _bid, "Incorrect bid amount.");
        require(block.timestamp <= auctionEnd, "Auction has ended.");
        require(currentHighestBid < _bid, "Bid must be higher than the current highest bid.");

        Bid memory newBid = Bid(_msgSender(), _bid, block.timestamp);
        bids.push(newBid);
        currentHighestBid = _bid;
        highestBidder = bids[bids.length - 1];
    }

    function endAuction() public onlyOwner {
        require(block.timestamp > auctionEnd, "Auction has not ended.");
        require(highestBidder.bidder != msg.sender, "The owner cannot win the auction.");

        transferFrom(highestBidder.bidder, msg.sender, tokenId());
        emit BidWon(highestBidder.bidder, msg.sender, currentHighestBid);
    }

    event BidWon(address indexed bidder, address indexed winner, uint256 indexed amount);
}
```

This smart contract uses OpenZeppelin libraries for ERC721 token standard, access control, and safe math operations. It allows users to bid on a single item (represented as an ERC721 token) by calling the `placeBid` function with the bid amount. The highest bidder at the end of the auction (defined by the `auctionEnd` variable) becomes the owner of the item. The contract owner can end the auction using the `endAuction` function. The `BidWon` event is emitted when the auction ends, allowing other contracts or users to react to the winning bid.

